class Solution {
  public int[] countWordOccurrences(String[] chunks, String[] queries) {
    StringBuilder sb = new StringBuilder();
    for (String c : chunks) sb.append(c);
    String s = sb.toString();
    int n = s.length();
    java.util.HashMap<String, Integer> count = new java.util.HashMap<>();
    int i = 0;
    while (i < n) {
      if (!isWordChar(s, i)) {
        i++;
        continue;
      }
      int j = i;
      while (j < n && isWordChar(s, j)) j++;
      count.merge(s.substring(i, j), 1, Integer::sum);
      i = j;
    }
    int[] ans = new int[queries.length];
    for (int q = 0; q < queries.length; q++) ans[q] = count.getOrDefault(queries[q], 0);
    return ans;
  }

  private static boolean isWordChar(String s, int i) {
    char c = s.charAt(i);
    if (c >= 'a' && c <= 'z') return true;
    return c == '-'
        && i > 0
        && i + 1 < s.length()
        && Character.isLowerCase(s.charAt(i - 1))
        && Character.isLowerCase(s.charAt(i + 1));
  }
}
